// ---- BUILT FROM src/email/cleanup.js — edit the repo, not n8n ----
// Email cleanup: turns an inbound email into a Ticket title and body.
// Pure functions, no imports and no n8n globals (ADR 0008). The input has the
// shape n8n's IMAP trigger gives with format "resolved" (mailparser):
// { subject, from: { value: [{ name, address }] }, html (string or false), text, messageId }.

const MAX_TITLE = 2000; // Notion rejects rich text over 2000 characters.

// ---- Subject ----

const PREFIX_RE = /^\s*\[?\s*(?:re|fwd?|tr|rv)\s*(?:[[(]\s*\d+\s*[\])])?\s*:\s*/i;
const FORWARD_SUBJECT_RE = /^\s*\[?\s*(?:fwd?|tr|rv)\s*:/i;

function cleanSubject(subject) {
  let s = String(subject ?? '');
  let bracketed = false;
  for (let prev = null; s !== prev;) {
    prev = s;
    if (/^\s*\[/.test(s) && PREFIX_RE.test(s)) bracketed = true;
    s = s.replace(PREFIX_RE, '');
  }
  return (bracketed ? removeFirstUnmatchedBracket(s) : s).trim();
}

// "[Fwd: Hello] see [doc]" → after the prefix, "Hello] see [doc]": drop the "]" that closed "[Fwd:".
function removeFirstUnmatchedBracket(s) {
  let depth = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '[') depth++;
    else if (s[i] === ']' && depth-- === 0) return s.slice(0, i) + s.slice(i + 1);
  }
  return s;
}

// ---- Encoding repair ----

// Windows-1252 characters for bytes 0x80–0x9F, as a mis-decoder shows them.
const CP1252 = {
  '€': 0x80, '‚': 0x82, 'ƒ': 0x83, '„': 0x84, '…': 0x85, '†': 0x86, '‡': 0x87, 'ˆ': 0x88,
  '‰': 0x89, 'Š': 0x8a, '‹': 0x8b, 'Œ': 0x8c, 'Ž': 0x8e, '‘': 0x91, '’': 0x92, '“': 0x93,
  '”': 0x94, '•': 0x95, '–': 0x96, '—': 0x97, '˜': 0x98, '™': 0x99, 'š': 0x9a, '›': 0x9b,
  'œ': 0x9c, 'ž': 0x9e, 'Ÿ': 0x9f,
};
const CONT = '[\\u0080-\\u00BF€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ]';
// A UTF-8 lead byte (0xC2–0xF4) read as Latin-1/Windows-1252, followed by continuation bytes.
const MOJIBAKE_RE = new RegExp('[\\u00C2-\\u00F4]' + CONT + '+', 'g');

function byteOf(ch) {
  const code = ch.charCodeAt(0);
  return code <= 0xff ? code : CP1252[ch];
}

// Strict UTF-8 decoding of a byte run; returns null if the bytes aren't valid UTF-8.
function decodeUtf8(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length;) {
    const b = bytes[i];
    const len = b >= 0xf0 ? 4 : b >= 0xe0 ? 3 : b >= 0xc2 ? 2 : 0;
    if (!len || i + len > bytes.length) return null;
    let cp = b & (0xff >> (len + 1));
    for (let k = 1; k < len; k++) {
      const c = bytes[i + k];
      if ((c & 0xc0) !== 0x80) return null;
      cp = (cp << 6) | (c & 0x3f);
    }
    if (cp > 0x10ffff || (len === 3 && cp < 0x800) || (len === 4 && cp < 0x10000)) return null;
    out += String.fromCodePoint(cp);
    i += len;
  }
  return out;
}

// Repairs UTF-8 text that was decoded as Latin-1 or Windows-1252 ("Ã©tÃ©" → "été").
// Each broken run is repaired on its own, so correct text around it is untouched.
function fixDoubleEncoding(str) {
  return String(str ?? '').replace(MOJIBAKE_RE, (run) => {
    // A run can end with a correct character (e.g. "Ã©tÃ©" then "…"): try the longest valid prefix.
    for (let end = run.length; end >= 2; end--) {
      const bytes = [...run.slice(0, end)].map(byteOf);
      if (bytes.some((b) => b === undefined)) continue;
      const decoded = decodeUtf8(bytes);
      if (decoded !== null) return decoded + run.slice(end);
    }
    return run;
  });
}

// ---- HTML to text ----

const ENTITIES = {
  nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'",
  laquo: '«', raquo: '»', lsquo: '‘', rsquo: '’', sbquo: '‚', ldquo: '“', rdquo: '”', bdquo: '„',
  ndash: '–', mdash: '—', hellip: '…', bull: '•', middot: '·', euro: '€', copy: '©', reg: '®',
  trade: '™', deg: '°', sect: '§', para: '¶', times: '×', divide: '÷', iexcl: '¡', iquest: '¿',
  cent: '¢', pound: '£', yen: '¥', shy: '', ordf: 'ª', ordm: 'º', micro: 'µ', plusmn: '±',
  frac12: '½', frac14: '¼', frac34: '¾', sup2: '²', sup3: '³', thinsp: ' ', ensp: ' ', emsp: ' ',
  zwnj: '', zwj: '', lrm: '', rlm: '', szlig: 'ß', oelig: 'œ', OElig: 'Œ', aelig: 'æ', AElig: 'Æ',
};
// Accented letters: &eacute; &Agrave; &ccedil; &ntilde; &ouml; &oslash; &aring; …
const ACCENTS = { acute: '́', grave: '̀', circ: '̂', uml: '̈', tilde: '̃', cedil: '̧', ring: '̊' };

function namedEntity(name) {
  if (name in ENTITIES) return ENTITIES[name];
  const m = name.match(/^([a-zA-Z])(acute|grave|circ|uml|tilde|cedil|ring)$/);
  if (m) return (m[1] + ACCENTS[m[2]]).normalize('NFC');
  if (name === 'oslash') return 'ø';
  if (name === 'Oslash') return 'Ø';
  return null;
}

function decodeEntities(str) {
  return String(str ?? '').replace(/&(#\d+|#[xX][0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);/g, (whole, name) => {
    if (name[0] === '#') {
      const code = name[1] === 'x' || name[1] === 'X' ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10);
      return code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : whole;
    }
    const ch = namedEntity(name);
    return ch === null ? whole : ch;
  });
}

const BLOCK = 'p|div|tr|h[1-6]|blockquote|ul|ol|li|table|pre|address|section|article|header|footer|dl|dt|dd|center';
const EDGE = '\u0001'; // a block edge: becomes a line break, but several in a row count once

function htmlToText(html) {
  const marked = String(html ?? '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<(head|style|script|title|xml)\b[\s\S]*?<\/\1\s*>/gi, '')
    .replace(/\s+/g, ' ') // source newlines are just whitespace in HTML
    .replace(/<br\b[^>]*>/gi, '\n')
    .replace(/<hr\b[^>]*>/gi, EDGE + '________________________________' + EDGE)
    .replace(/<li\b[^>]*>/gi, EDGE + '- ')
    .replace(new RegExp('</?(?:' + BLOCK + ')\\b[^>]*>', 'gi'), EDGE)
    .replace(/<\/t[dh]\s*>/gi, ' ')
    .replace(/<[^>]*>/g, '');
  const text = marked
    .replace(new RegExp(EDGE + '(?:[ ]*' + EDGE + ')*', 'g'), EDGE)
    .replace(new RegExp('(^|\\n)[ ]*' + EDGE, 'g'), '$1') // an edge right after a <br> adds nothing
    .replaceAll(EDGE, '\n');
  return decodeEntities(text);
}

// ---- Text cleanup ----

function normaliseWhitespace(str) {
  return String(str ?? '')
    .replace(/\r\n?/g, '\n')
    .replace(/[     \t]/g, ' ')
    .replace(/[​-‍﻿]/g, '')
    .split('\n')
    .map((line) => line.replace(/ {2,}/g, ' ').trim())
    .filter((line, i, lines) => line !== '' || (i > 0 && lines[i - 1] !== ''))
    .join('\n')
    .trim();
}

const FORWARD_BODY_RE = /^\s*(?:-{2,}\s*(?:forwarded message|message transféré|message réexpédié)|begin forwarded message\s*:|début du message (?:réexpédié|transféré)\s*:)/im;

function isForward(subject, text) {
  return FORWARD_SUBJECT_RE.test(String(subject ?? '')) || FORWARD_BODY_RE.test(String(text ?? ''));
}

const ORIGINAL_MESSAGE_RE = /^-{2,}\s*(?:original message|message d'origine|message original)\s*-{2,}$/i;
const ATTRIBUTION_START_RE = /^(?:on|le)\s/i;
const ATTRIBUTION_END_RE = /(?:\bwrote|\ba écrit)\s*:\s*$/i;
const HEADER_FROM_RE = /^(?:from|de)\s*:/i;
const HEADER_SENT_RE = /^(?:sent|envoyé|date)\s*:/i;
const HEADER_SUBJECT_RE = /^(?:subject|objet)\s*:/i;
const SEPARATOR_RE = /^(?:_{5,}|-{5,})$/;

// The text before line i; the whole text if i is -1 or nothing would be left.
function cutAt(text, lines, i) {
  if (i < 0) return text;
  const kept = lines.slice(0, i).join('\n').trim();
  return kept === '' ? text : kept;
}

// Index of the first line of quoted history, or -1.
function quotedHistoryStart(lines) {
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line.startsWith('>') || ORIGINAL_MESSAGE_RE.test(line)) return i;
    if (ATTRIBUTION_START_RE.test(line)) {
      // Clients wrap long attributions ("On …, Name <addr>\nwrote:").
      for (let k = i; k < Math.min(i + 3, lines.length); k++) {
        if (ATTRIBUTION_END_RE.test(lines[k].trim())) return i;
      }
    }
    if (HEADER_FROM_RE.test(line)) {
      const next = lines.slice(i + 1, i + 6).map((l) => l.trim());
      if (next.some((l) => HEADER_SENT_RE.test(l)) && next.some((l) => HEADER_SUBJECT_RE.test(l))) {
        let start = i;
        while (start > 0 && (lines[start - 1].trim() === '' || SEPARATOR_RE.test(lines[start - 1].trim()))) start--;
        return start;
      }
    }
  }
  return -1;
}

function stripQuotedHistory(text) {
  const lines = String(text ?? '').split('\n');
  return cutAt(text, lines, quotedHistoryStart(lines));
}

const NOTICE_RES = [
  /^(?:confidentiality notice|avis de confidentialit[ée]|confidentialit[ée]|confidential(?:ity)?|disclaimer)\s*[:\-–]/i,
  /\bthis (?:e-?mail|message|communication|transmission)\b.{0,120}\b(?:confidential|privileged)\b/i,
  /\b(?:ce|le présent) (?:courriel|message|courrier électronique|document)\b.{0,160}\bconfidenti/i,
];

// Removes an EN/FR confidentiality notice and everything after it,
// unless it is the first thing in the message.
function stripConfidentialityNotice(text) {
  const lines = String(text ?? '').split('\n');
  return cutAt(text, lines, lines.findIndex((line) => NOTICE_RES.some((re) => re.test(line.trim()))));
}

// ---- Sender ----

function parseSender(from) {
  const first = from?.value?.[0] ?? {};
  const email = String(first.address ?? '').trim().toLowerCase();
  let name = normaliseWhitespace(fixDoubleEncoding(String(first.name ?? ''))).replace(/^["']+|["']+$/g, '').trim();
  const comma = name.match(/^([^,]+),\s*([^,]+)$/);
  if (comma) name = comma[2] + ' ' + comma[1];
  if (!name || name.toLowerCase() === email) return { name: email, firstName: '', lastName: '', email };
  const [firstName, ...rest] = name.split(/\s+/);
  return { name, firstName, lastName: rest.join(' '), email };
}

// ---- Whole email ----

function cleanEmail(mail) {
  const subject = fixDoubleEncoding(decodeEntities(String(mail?.subject ?? '')));
  const raw = mail?.html ? htmlToText(mail.html) : String(mail?.text ?? '');
  const text = normaliseWhitespace(fixDoubleEncoding(raw));
  const forward = isForward(subject, text);

  let body = forward ? text : stripQuotedHistory(text);
  body = normaliseWhitespace(stripConfidentialityNotice(body));

  return {
    title: (cleanSubject(subject) || '(no subject)').slice(0, MAX_TITLE),
    body,
    isForward: forward,
    sender: parseSender(mail?.from),
    messageId: mail?.messageId ?? '',
  };
}
// ---- END src/email/cleanup.js ----
// ---- BUILT FROM src/email/thread.js — edit the repo, not n8n ----
// Threading: the Message-IDs an inbound email answers, from its In-Reply-To and
// References headers, to look up the Ticket it belongs to (Free tier matching).
// Pure functions, no imports and no n8n globals (ADR 0008). The input has the
// shape n8n's IMAP trigger gives with format "resolved" (mailparser):
// inReplyTo is a string; references is a string, or an array when there are several.

const MAX_THREAD_IDS = 30; // keeps the Notion query filter small

const ID_RE = /<[^<>\s]+>|[^<>\s,]+@[^<>\s,]+/g;

// Every Message-ID in a header value, in order, always in <angle brackets>.
function messageIds(value) {
  const values = Array.isArray(value) ? value : [value];
  return values.flatMap((v) => String(v ?? '').match(ID_RE) ?? []).map((id) => (id.startsWith('<') ? id : '<' + id + '>'));
}

// The Message-IDs to look a Ticket up by, most recent first: In-Reply-To, then
// References from newest to oldest. A long thread keeps its newest ids and its
// first one, the email that usually created the Ticket.
function threadMessageIds(mail) {
  const references = messageIds(mail?.references);
  const own = messageIds(mail?.messageId)[0];
  const ids = [...new Set([...messageIds(mail?.inReplyTo), ...[...references].reverse()])].filter((id) => id !== own);
  if (ids.length <= MAX_THREAD_IDS) return ids;
  const first = references[0];
  return [...ids.filter((id) => id !== first).slice(0, MAX_THREAD_IDS - 1), first];
}
// ---- END src/email/thread.js ----
// ---- BUILT FROM src/inbound/ticket.js — edit the repo, not n8n ----
// Notion API requests for the Inbound workflow: add a same-thread follow-up to its
// Ticket as a comment, or find or create the Contact for the email's From address,
// then create the Ticket. Pure functions, no imports (ADR 0008).
// Property names match the Notion template (docs/notion-template.md).

const API = 'https://api.notion.com/v1';
const MAX_TEXT = 2000; // characters per rich text piece
const MAX_BLOCKS = 100; // children per request

const richText = (s) => {
  const pieces = [];
  for (let i = 0; i < s.length; i += MAX_TEXT) pieces.push({ type: 'text', text: { content: s.slice(i, i + MAX_TEXT) } });
  return pieces;
};

const paragraph = (s) => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: richText(s) } });

// One paragraph block per paragraph; past the block limit, the rest goes into the last block.
function textToBlocks(text, maxBlocks = MAX_BLOCKS) {
  const paragraphs = String(text ?? '').split(/\n{2,}/).filter((p) => p.trim() !== '');
  if (paragraphs.length > maxBlocks) {
    paragraphs.splice(maxBlocks - 1, Infinity, paragraphs.slice(maxBlocks - 1).join('\n\n'));
  }
  return paragraphs.map(paragraph);
}

function findContactRequest(email, contactsDatabaseId) {
  return {
    method: 'POST',
    url: API + '/databases/' + contactsDatabaseId + '/query',
    body: { filter: { property: 'Email', email: { equals: email } }, page_size: 1 },
  };
}

function createContactRequest(sender, contactsDatabaseId) {
  return {
    method: 'POST',
    url: API + '/pages',
    body: {
      parent: { database_id: contactsDatabaseId },
      properties: {
        Name: { title: richText(sender.name || sender.email) },
        'First name': { rich_text: richText(sender.firstName || '') },
        'Last name': { rich_text: richText(sender.lastName || '') },
        Email: { email: sender.email },
      },
    },
  };
}

// De-duplication: a Ticket already created from this email. Message-IDs will
// hold several ids once replies are threaded, hence "contains". An email without
// a Message-ID can't be matched; the workflow treats it as new whatever this finds.
function findTicketRequest(messageId, ticketsDatabaseId) {
  return {
    method: 'POST',
    url: API + '/databases/' + ticketsDatabaseId + '/query',
    body: {
      filter: { property: 'Message-IDs', rich_text: messageId ? { contains: messageId } : { is_empty: true } },
      page_size: 1,
    },
  };
}

const notStored = ({ name, reason }) => ({
  object: 'block',
  type: 'callout',
  callout: { icon: { type: 'emoji', emoji: '⚠️' }, rich_text: richText('Attachment not stored: ' + name + ' (' + reason + ')') },
});

// The email text, then a callout per attachment that could not be stored.
function emailBlocks(cleaned, uploads) {
  const notes = uploads.failed.map(notStored).slice(0, MAX_BLOCKS - 1);
  return [...textToBlocks(cleaned.body, MAX_BLOCKS - notes.length), ...notes];
}

// Status is left out so the Ticket gets the database's default option (New),
// which keeps working if the Desk owner renames the options (ADR 0006).
// cleaned: the result of cleanEmail (src/email/cleanup.js).
// uploads: the result of collectUploads (src/inbound/attachments.js).
function ticketPage(cleaned, contactId, ticketsDatabaseId, uploads) {
  const properties = {
    Title: { title: richText(cleaned.title) },
    Requester: { relation: [{ id: contactId }] },
    'Message-IDs': { rich_text: richText(cleaned.messageId || '') },
  };
  if (uploads.files.length) {
    properties.Attachments = { files: uploads.files.map(({ id, name }) => ({ type: 'file_upload', file_upload: { id }, name })) };
  }
  return { parent: { database_id: ticketsDatabaseId }, properties };
}

const NO_UPLOADS = { files: [], failed: [] };

// The Ticket with the email as its whole body: for a Tickets database without a default template.
function createTicketRequest(cleaned, contactId, ticketsDatabaseId, uploads = NO_UPLOADS) {
  return {
    method: 'POST',
    url: API + '/pages',
    body: { ...ticketPage(cleaned, contactId, ticketsDatabaseId, uploads), children: emailBlocks(cleaned, uploads) },
  };
}

// The Ticket from the Tickets database's default template, which the Desk owner
// designs in Notion. Notion applies it in the background and refuses children
// alongside it; addEmailRequest then puts the email above the template's content.
// The Message-ID is left out until the email is in (storeMessageIdRequest): a
// retry after a failed add then creates the Ticket again instead of skipping it.
function createTicketFromTemplateRequest(cleaned, contactId, ticketsDatabaseId, uploads = NO_UPLOADS) {
  const page = ticketPage(cleaned, contactId, ticketsDatabaseId, uploads);
  delete page.properties['Message-IDs'];
  return {
    method: 'POST',
    url: API + '/pages',
    body: { ...page, template: { type: 'default' } },
  };
}

function storeMessageIdRequest(pageId, messageId) {
  return {
    method: 'PATCH',
    url: API + '/pages/' + pageId,
    body: { properties: { 'Message-IDs': { rich_text: richText(messageId || '') } } },
  };
}

// errorItem: what n8n's HTTP Request node puts on its error output. Notion answers
// a plain validation_error, so its message is the only way to tell this case apart.
function isNoDefaultTemplateError(errorItem) {
  return /no default template/i.test(JSON.stringify(errorItem ?? {}));
}

function addEmailRequest(pageId, cleaned, uploads = NO_UPLOADS) {
  return {
    method: 'PATCH',
    url: API + '/blocks/' + pageId + '/children',
    body: { children: emailBlocks(cleaned, uploads), position: { type: 'start' } },
  };
}

// ---- Same-thread follow-ups ----

const MAX_RICH_TEXT = 100; // rich text pieces per comment or property

// The oldest Ticket whose Message-IDs hold any of the ids (from threadMessageIds, src/email/thread.js).
// The ids keep their <angle brackets>, so one id never matches inside a longer one.
function findThreadTicketRequest(messageIds, ticketsDatabaseId) {
  return {
    method: 'POST',
    url: API + '/databases/' + ticketsDatabaseId + '/query',
    body: {
      filter: { or: messageIds.map((id) => ({ property: 'Message-IDs', rich_text: { contains: id } })) },
      sorts: [{ timestamp: 'created_time', direction: 'ascending' }],
      page_size: 1,
    },
  };
}

const MAX_COMMENT_FILES = 3; // attachments per comment

const bold = (s) => ({ type: 'text', text: { content: s.slice(0, MAX_TEXT) }, annotations: { bold: true } });
const commentAttachments = (files) => files.map(({ id }) => ({ type: 'file_upload', file_upload_id: id }));
const comment = (ticketId, richText, files) => ({
  method: 'POST',
  url: API + '/comments',
  body: { parent: { page_id: ticketId }, rich_text: richText, ...(files.length ? { attachments: commentAttachments(files) } : {}) },
});

// A follow-up as a comment: the author's name in bold, then the cleaned text,
// then a line per attachment that could not be stored. Starting with the name
// means a customer email never starts with the Reply marker.
// Stored attachments go on the comment, 3 at most (Notion's limit); the rest go
// on more comments of 3, each saying it continues the follow-up.
// Text past Notion's 100-piece limit (about 200,000 characters) is dropped, never the notes.
// uploads: the result of collectUploads (src/inbound/attachments.js).
function addCommentRequests(ticketId, cleaned, uploads = NO_UPLOADS) {
  const name = cleaned.sender.name;
  const notes = uploads.failed.map(({ name: file, reason }) => '⚠️ Attachment not stored: ' + file + ' (' + reason + ')');
  const notesText = notes.length ? richText((cleaned.body ? '\n\n' : '\n') + notes.join('\n')) : [];
  const body = cleaned.body ? richText('\n' + cleaned.body).slice(0, MAX_RICH_TEXT - 1 - notesText.length) : [];
  const batches = [];
  for (let i = 0; i < uploads.files.length; i += MAX_COMMENT_FILES) batches.push(uploads.files.slice(i, i + MAX_COMMENT_FILES));
  const [first = [], ...rest] = batches;
  return [
    comment(ticketId, [bold(name), ...body, ...notesText].slice(0, MAX_RICH_TEXT), first),
    ...rest.map((files) => comment(ticketId, [bold(name + ' (attachments, continued)')], files)),
  ];
}

// Adds the follow-up's Message-ID to the Ticket's Message-IDs (one per line),
// so a later email that only answers this follow-up still finds the Ticket, and
// fetching the follow-up again is skipped as a duplicate (findTicketRequest).
// Sent after the comment, like storeMessageIdRequest: a failed comment is retried.
// ticket: the page from the findThreadTicketRequest result.
function appendMessageIdRequest(ticket, messageId) {
  const stored = (ticket.properties['Message-IDs']?.rich_text ?? []).map((r) => r.plain_text ?? r.text?.content ?? '').join('');
  const ids = stored.split(/\s+/).filter(Boolean);
  if (messageId && !ids.includes(messageId)) ids.push(messageId);
  return {
    method: 'PATCH',
    url: API + '/pages/' + ticket.id,
    body: { properties: { 'Message-IDs': { rich_text: richText(ids.join('\n')) } } },
  };
}
// ---- END src/inbound/ticket.js ----
// ---- BUILT FROM src/inbound/attachments.js — edit the repo, not n8n ----
// Attachments of an inbound email, stored on its Ticket through the Notion
// File Upload API: start an upload per file, send the file, then attach the
// upload ids to the Ticket. Pure functions, no imports (ADR 0008).

const FILE_UPLOADS = 'https://api.notion.com/v1/file_uploads';

// n8n's IMAP trigger puts attachment n in binary key attachment_<n>.
const ATTACHMENT_KEY = /^attachment_(\d+)$/;

const fallbackName = (index, mimeType) => {
  const subtype = /^[a-z]+\/([a-z0-9]+)$/i.exec(mimeType ?? '')?.[1];
  return 'attachment-' + (index + 1) + (subtype && subtype !== 'octet' && !/stream/.test(subtype) ? '.' + subtype : '');
};

// The request's multipart body (the file itself) is set in the Send file node.
function sendFileRequest(uploadId) {
  return { method: 'POST', url: FILE_UPLOADS + '/' + uploadId + '/send' };
}

function startUploadRequest(filename, contentType) {
  return {
    method: 'POST',
    url: FILE_UPLOADS,
    body: { mode: 'single_part', filename, content_type: contentType },
  };
}

const attachmentFiles = (binary) => Object.entries(binary ?? {})
  .map(([key, file]) => ({ n: Number(ATTACHMENT_KEY.exec(key)?.[1]), file }))
  .filter(({ n }) => Number.isInteger(n))
