  return {
    method: 'POST',
    url: API + '/databases/' + ticketsDatabaseId + '/query',
    body: {
      filter: { property: 'Message-IDs', rich_text: messageId ? { contains: messageId } : { is_empty: true } },
      page_size: 1,
